SELECT (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='bk_rag' AND ((table_name='rag_document_state' AND column_name IN ('space_id','document_id','latest_revision','latest_hash','latest_payload_hash','latest_event_id','schema_version','tombstone','state','keyword_applied_revision','vector_applied_revision','keyword_attempts','vector_attempts','keyword_error','vector_error','keyword_next_retry_at','vector_next_retry_at','reconcile_at','updated_at')) OR (table_name='rag_index_event' AND column_name IN ('event_id','space_id','document_id','revision','content_hash','payload_hash','schema_version','operation','canonical_payload','state','error_code','created_at','received_at'))))=32 AND (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='bk_rag' AND table_name IN ('rag_document_state','rag_index_event') AND engine='InnoDB' AND table_collation='utf8mb4_bin')=2;
